/**
 * Buying inside the Android app.
 *
 * Google Play must be the seller here: their rules do not allow anything
 * else for digital goods, and breaking that can get the app removed. So the
 * same plan is bought two ways — Paddle's overlay on the web, Play's sheet
 * in the app — and both end in the same place, with the server deciding what
 * was actually bought.
 *
 * Nothing in this file decides that anybody has paid. Play hands back a
 * token; the server asks Google what the token is worth. A token this file
 * invented would buy nothing.
 */
import { shellPlatform } from '@/lib/platform/detect.js';

/** The native plugin, as the web layer sees it. */
interface PlayBilling {
  /** Whether this device and country can buy a subscription at all. */
  isAvailable(): Promise<{ available: boolean }>;
  /**
   * Opens Play's purchase sheet. Resolves with the token when it worked,
   * and with `cancelled` when the person backed out, which is not an error.
   */
  purchase(options: {
    productId: string;
    accountId: string;
    /** The base plan and offer to buy; absent on a plain purchase (and on older shells). */
    basePlanId?: string;
    offerId?: string;
    offerTag?: string;
  }): Promise<{
    cancelled: boolean;
    purchaseToken?: string;
  }>;
  /** Every subscription token this device holds. */
  purchases(): Promise<{ purchaseTokens: string[] }>;
  /**
   * The product's base plans and offers as Play sells them on this device,
   * with Play's own localised prices. Missing on shells older than the
   * offers (the call then rejects).
   */
  offerDetails(options: { productId: string }): Promise<{ offers: PlayOfferDetails[] }>;
}

/** One base plan or offer, as Play describes it. */
export interface PlayOfferDetails {
  basePlanId: string;
  offerId?: string;
  tags: string[];
  phases: PlayPricingPhase[];
}

/** One pricing phase of a Play offer: what is charged, how often, how many times. */
export interface PlayPricingPhase {
  formattedPrice: string;
  priceAmountMicros: string;
  priceCurrencyCode: string;
  /** ISO 8601 duration, "P1Y". */
  billingPeriod: string;
  billingCycleCount: number;
  /**
   * Play's RecurrenceMode as the shell names it: "infinite", "finite" or
   * "nonRecurring" (an unknown one arrives as its number, as a string).
   */
  recurrenceMode: string | number;
}

/** The Play offer to buy, as the server named it. */
export interface PlayOfferRefs {
  productId: string;
  basePlanId: string;
  offerId: string;
  offerTag?: string | undefined;
}

let plugin: Promise<{ play: PlayBilling }> | undefined;

/**
 * Registered on first use, and only then is Capacitor's bridge loaded, so a
 * browser that never buys through Play never downloads it. Every entry point
 * below checks the platform first.
 *
 * The plugin comes wrapped in an object, never as a promise's value on its
 * own: Capacitor's proxy answers to every property name, `then` included,
 * so resolving a promise with it calls a native method named "then" that
 * does not exist, and the promise never settles. Handing the proxy over
 * bare made every Play call wait for ever.
 */
function billing(): Promise<{ play: PlayBilling }> {
  plugin ??= import('@capacitor/core').then(({ registerPlugin }) => ({
    play: registerPlugin<PlayBilling>('Billing'),
  }));
  return plugin;
}

/** Whether this build is the Android app, where Play is the only seller. */
export function onAndroid(): boolean {
  return shellPlatform() === 'android';
}

/**
 * Whether this build is the iPhone app. Apple's rules (App Store Review
 * Guideline 3.1.1) allow only its own in-app purchase for digital goods, and
 * the app has none yet, so nothing in it may sell, link to a checkout or
 * unlock Pro with a code of ours. The server's `selling.ios` switch is not
 * enough on its own: there is no StoreKit purchase for it to switch on.
 */
export function onIOS(): boolean {
  return shellPlatform() === 'ios';
}

/** What a purchase attempt ended as, in the same words the web one uses. */
export type Outcome = { kind: 'bought'; purchaseToken: string } | { kind: 'closed' };

/**
 * Opens Play's sheet for one plan. The account travels with the purchase and
 * comes back to the server on Google's side of it; it is the only link
 * between a payment and a person, which is why the server refuses a purchase
 * that carries somebody else's.
 */
export async function buyOnPlay(plan: string, accountId: string, offer?: PlayOfferRefs): Promise<Outcome> {
  const result = await (
    await billing()
  ).play.purchase(
    offer === undefined
      ? { productId: plan, accountId }
      : {
          productId: offer.productId,
          accountId,
          basePlanId: offer.basePlanId,
          offerId: offer.offerId,
          ...(offer.offerTag === undefined ? {} : { offerTag: offer.offerTag }),
        },
  );
  if (result.cancelled || result.purchaseToken === undefined) return { kind: 'closed' };
  return { kind: 'bought', purchaseToken: result.purchaseToken };
}

/**
 * The tokens this device already holds.
 *
 * This is what makes a reinstall, a new phone, or a purchase that finished
 * while the app was closed work: each token goes to the server, which asks
 * Google what it is worth. A device with nothing to restore answers with an
 * empty list, which is the ordinary case and not a failure.
 */
export async function heldPurchases(): Promise<string[]> {
  if (!onAndroid()) return [];
  try {
    const { purchaseTokens } = await (await billing()).play.purchases();
    return purchaseTokens;
  } catch {
    // Play services missing, or the sheet unavailable in this country.
    // Nothing to restore is the right answer either way.
    return [];
  }
}

/** Whether Play can sell on this device at all. */
export async function playCanSell(): Promise<boolean> {
  if (!onAndroid()) return false;
  try {
    const { available } = await (await billing()).play.isAvailable();
    return available;
  } catch {
    return false;
  }
}

/**
 * What Play says about one product on this device:
 *
 * - `listed`: its base plans and offers, with Play's own localised prices.
 * - `unsupported`: a shell older than `offerDetails`, which cannot be asked.
 *   Those phones keep the server's figures, as they always have; Play's
 *   sheet still shows and charges its own price.
 * - `failed`: Play did not answer (no Play services, no connection, too
 *   slow). Nothing is shown rather than a price Play may not charge.
 */
export type PlayCatalog =
  { kind: 'listed'; offers: PlayOfferDetails[] } | { kind: 'unsupported' } | { kind: 'failed' };

/**
 * How long Play gets to list a product before the screen stops waiting.
 * Play's billing connection can hang on a device with a broken Play Store;
 * the plan must not wait for it for ever.
 */
const PLAY_PATIENCE_MS = 8000;

const catalogs = new Map<string, Promise<PlayCatalog>>();
/** The answers that have arrived, for a caller that cannot wait (`apply`). */
const settled = new Map<string, PlayCatalog>();

/** Capacitor's code for a method the native side does not have. */
function unimplemented(error: unknown): boolean {
  return (
    typeof error === 'object' && error !== null && (error as { code?: unknown }).code === 'UNIMPLEMENTED'
  );
}

/**
 * Play's catalogue for one product, asked once per run of the app and
 * shared by every screen. A failure is not kept, so the next look asks
 * again. Anywhere but Android: `unsupported`.
 */
export function playCatalog(productId: string): Promise<PlayCatalog> {
  if (!onAndroid()) return Promise.resolve({ kind: 'unsupported' });
  const kept = catalogs.get(productId);
  if (kept !== undefined) return kept;
  const ask = async (): Promise<PlayCatalog> => {
    const { offers } = await (await billing()).play.offerDetails({ productId });
    return { kind: 'listed', offers: Array.isArray(offers) ? offers : [] };
  };
  let timer: ReturnType<typeof setTimeout> | undefined;
  const late = new Promise<PlayCatalog>((resolve) => {
    timer = setTimeout(() => {
      resolve({ kind: 'failed' });
    }, PLAY_PATIENCE_MS);
  });
  const asked = Promise.race([
    ask().catch((error: unknown): PlayCatalog => ({ kind: unimplemented(error) ? 'unsupported' : 'failed' })),
    late,
  ]).then((answer) => {
    clearTimeout(timer);
    if (answer.kind === 'failed') catalogs.delete(productId);
    return answer;
  });
  catalogs.set(productId, asked);
  return asked;
}

/** The catalogue the last look found, for a caller that cannot wait. */
export function playCatalogNow(productId: string): PlayCatalog | undefined {
  return settled.get(productId);
}

/** Every product's catalogue at once, remembered for `playCatalogNow`. */
export async function loadPlayCatalogs(productIds: readonly string[]): Promise<Map<string, PlayCatalog>> {
  const answers = await Promise.all(productIds.map(async (id) => [id, await playCatalog(id)] as const));
  for (const [id, answer] of answers) {
    if (answer.kind === 'failed') settled.delete(id);
    else settled.set(id, answer);
  }
  return new Map(answers);
}

/** Forgets every catalogue, so a test starts from nothing. Tests only. */
export function forgetPlayCatalogs(): void {
  catalogs.clear();
  settled.clear();
  plugin = undefined;
}

/**
 * An offer's two prices as Play words them, for `useOfferWords`:
 * `words` when Play lists the offer, `server` on a shell that cannot ask
 * Play (the server's figures stand there), `none` when Play answered
 * without the offer or did not answer: the offer is then not shown, and
 * its plan is sold at Play's own price.
 */
export type PlayOfferAnswer =
  { kind: 'words'; first: string; renewal: string | undefined } | { kind: 'server' } | { kind: 'none' };

export async function playOfferWords(refs: PlayOfferRefs): Promise<PlayOfferAnswer> {
  if (!onAndroid()) return { kind: 'server' };
  const catalog = await playCatalog(refs.productId);
  if (catalog.kind === 'unsupported') return { kind: 'server' };
  if (catalog.kind === 'failed') return { kind: 'none' };
  const words = pickPlayOfferWords(catalog.offers, refs);
  return words === undefined ? { kind: 'none' } : { kind: 'words', ...words };
}

/**
 * A plain plan's price as Play sells it: the base plan's own entry (no
 * offer id; the first one, which is the one a plain purchase buys) and its
 * phase that recurs for ever. Undefined when Play lists none, or its period
 * is not the expected one ("P1M", "P1Y"): a price shown wrong is worse than
 * none.
 */
export function pickPlayBasePhase(
  offers: readonly PlayOfferDetails[],
  billingPeriod: string,
): PlayPricingPhase | undefined {
  const base = offers.find((one) => one.offerId === undefined || one.offerId === '');
  const phase =
    base?.phases.find((one) => one.recurrenceMode === 'infinite' || String(one.recurrenceMode) === '1') ??
    (base?.phases.length === 1 ? base.phases[0] : undefined);
  if (phase === undefined || phase.formattedPrice === '' || phase.billingPeriod !== billingPeriod)
    return undefined;
  return phase;
}

/** The pure half of `playOfferWords`, for the tests. */
export function pickPlayOfferWords(
  offers: readonly PlayOfferDetails[],
  refs: PlayOfferRefs,
): { first: string; renewal: string | undefined } | undefined {
  const onPlan = offers.filter((one) => one.basePlanId === refs.basePlanId);
  const offer =
    onPlan.find((one) => one.offerId === refs.offerId) ??
    (refs.offerTag === undefined ? undefined : onPlan.find((one) => one.tags.includes(refs.offerTag ?? '')));
  const first = offer?.phases[0];
  if (offer === undefined || first === undefined || first.formattedPrice === '') return undefined;
  // Play's RecurrenceMode.INFINITE_RECURRING: the price that goes on after the offer.
  const forever = offer.phases.find(
    (phase, index) =>
      index > 0 && (phase.recurrenceMode === 'infinite' || String(phase.recurrenceMode) === '1'),
  );
  return { first: first.formattedPrice, renewal: forever?.formattedPrice };
}
